export function parseRanges(header, size) {
  if (!Number.isSafeInteger(size) || size < 0) {
    throw new TypeError('size must be a nonnegative safe integer');
  }
  if (typeof header !== 'string' || !header.startsWith('bytes=')) {
    throw new TypeError('Invalid byte range header');
  }

  const ranges = [];
  for (const part of header.slice(6).split(',')) {
    const match = /^(\d*)-(\d*)$/.exec(part.trim());
    if (!match || (match[1] === '' && match[2] === '')) {
      throw new TypeError('Invalid byte range syntax');
    }

    const start = match[1] === '' ? null : Number(match[1]);
    const end = match[2] === '' ? null : Number(match[2]);
    if ((start !== null && !Number.isSafeInteger(start)) ||
        (end !== null && !Number.isSafeInteger(end))) {
      throw new TypeError('Byte range integers must be safe');
    }
    if (start !== null && end !== null && start > end) {
      throw new TypeError('Byte range start exceeds end');
    }

    if (size === 0) continue;
    if (start === null) {
      if (end > 0) ranges.push([size - Math.min(end, size), size - 1]);
    } else if (start < size) {
      ranges.push([start, end === null ? size - 1 : Math.min(end, size - 1)]);
    }
  }
  return ranges;
}

