export function parseRanges(header, size) {
  if (!Number.isSafeInteger(size) || size < 0) {
    throw new TypeError('size must be a nonnegative safe integer');
  }
  if (typeof header !== 'string' || !header.startsWith('bytes=')) {
    throw new TypeError('Invalid range header');
  }

  const parseInteger = (digits) => {
    const value = Number(digits);
    if (!Number.isSafeInteger(value)) {
      throw new TypeError('Unsafe range integer');
    }
    return value;
  };

  const ranges = [];
  for (const part of header.slice(6).split(',')) {
    const match = /^(?:([0-9]+)-([0-9]*)|-([0-9]+))$/.exec(part.trim());
    if (!match) {
      throw new TypeError('Invalid range syntax');
    }

    if (match[3] !== undefined) {
      const length = parseInteger(match[3]);
      if (size > 0 && length > 0) {
        ranges.push([size - Math.min(length, size), size - 1]);
      }
      continue;
    }

    const start = parseInteger(match[1]);
    const explicitEnd = match[2] !== '';
    const end = explicitEnd ? parseInteger(match[2]) : size - 1;
    if (explicitEnd && start > end) {
      throw new TypeError('Reversed range');
    }
    if (start < size) {
      ranges.push([start, Math.min(end, size - 1)]);
    }
  }
  return ranges;
}

