export function parseCsv(text) {
  if (text.length === 0) return [];

  const rows = [];
  let row = [];
  let field = '';
  let state = 'start';
  let endedWithRowSeparator = false;

  for (let i = 0; i < text.length; i++) {
    const char = text[i];

    if (state === 'quoted') {
      if (char === '"') {
        if (text[i + 1] === '"') {
          field += '"';
          i++;
        } else {
          state = 'closed';
        }
      } else {
        field += char;
      }
      continue;
    }

    if (char === '\n' || char === '\r') {
      if (char === '\r') {
        if (text[i + 1] !== '\n') {
          throw new SyntaxError('Bare CR outside a quoted field');
        }
        i++;
      }
      row.push(field);
      rows.push(row);
      row = [];
      field = '';
      state = 'start';
      endedWithRowSeparator = true;
      continue;
    }

    endedWithRowSeparator = false;
    if (char === ',') {
      row.push(field);
      field = '';
      state = 'start';
    } else if (state === 'closed') {
      throw new SyntaxError('Unexpected character after closing quote');
    } else if (char === '"') {
      if (state !== 'start') {
        throw new SyntaxError('Quote may only begin a field');
      }
      state = 'quoted';
    } else {
      field += char;
      state = 'unquoted';
    }
  }

  if (state === 'quoted') {
    throw new SyntaxError('Unterminated quoted field');
  }
  if (!endedWithRowSeparator) {
    row.push(field);
    rows.push(row);
  }
  return rows;
}

