      if (char === '\r') {
        if (text[i + 1] !== '\n') {
          throw new SyntaxError('Bare CR outside a quoted field');
        }
        i++;
      }
      row.push(field);
      rows.push(row);
      row = [];
      field = '';
      state = 'start';
      rowStart = i + 1;
    } else if (char === '"' && state === 'start') {
      state = 'quoted';
