const isObject = value =>
  value !== null && typeof value === 'object' && !Array.isArray(value);

// Define properties directly so special names remain ordinary data keys.
const setOwn = (object, key, value) => {
  Object.defineProperty(object, key, {
    value,
    enumerable: true,
    writable: true,
    configurable: true,
  });
};

const copy = value => {
  if (Array.isArray(value)) return value.map(copy);
  if (!isObject(value)) return value;

  const result = {};
  for (const key of Object.keys(value)) {
    setOwn(result, key, copy(value[key]));
  }
  return result;
};

export function deepMerge(left, right) {
  if (!isObject(left) || !isObject(right)) return copy(right);

  const result = {};
  for (const key of Object.keys(left)) {
    if (!Object.hasOwn(right, key)) {
      setOwn(result, key, copy(left[key]));
    }
  }
  for (const key of Object.keys(right)) {
    setOwn(result, key, Object.hasOwn(left, key)
      ? deepMerge(left[key], right[key])
      : copy(right[key]));
  }
  return result;
}

