export function deepMerge(left, right) {
  const pending = [];

  function create(a, b) {
    if (b === null || typeof b !== 'object') return b;

    const result = Array.isArray(b) ? new Array(b.length) : {};
    pending.push({ left: a, right: b, result });
    return result;
  }

  const result = create(left, right);

  // Use an explicit work stack so deeply nested JSON does not exhaust the
  // JavaScript call stack. Every occurrence receives its own fresh container.
  while (pending.length) {
    const { left: a, right: b, result: target } = pending.pop();
    const merge = isObject(a) && isObject(b);
    const keys = new Set([
      ...(merge ? Reflect.ownKeys(a) : []),
      ...Reflect.ownKeys(b),
    ]);

    for (const key of keys) {
      if (Array.isArray(target) && key === 'length') continue;

      const inRight = Object.hasOwn(b, key);
      const value = inRight
        ? create(merge && Object.hasOwn(a, key) ? a[key] : undefined, b[key])
        : create(undefined, a[key]);

      // Defining data properties bypasses inherited setters such as __proto__.
      Object.defineProperty(target, key, {
        value,
        enumerable: true,
        writable: true,
        configurable: true,
      });
    }
  }

  return result;
