export class Emitter {
  #listeners = new Map();

  on(event, fn) {
    return this.#register(event, fn, false);
  }

  once(event, fn) {
    return this.#register(event, fn, true);
  }

  #register(event, fn, once) {
    let listeners = this.#listeners.get(event);
    if (!listeners) {
      listeners = new Set();
      this.#listeners.set(event, listeners);
    }

    const registration = { fn, once, consumed: false, unsubscribe: null };
    const unsubscribe = () => {
      listeners.delete(registration);
      if (listeners.size === 0 && this.#listeners.get(event) === listeners) {
        this.#listeners.delete(event);
      }
    };
    registration.unsubscribe = unsubscribe;
    listeners.add(registration);
    return unsubscribe;
  }

  emit(event, ...args) {
    const snapshot = [...(this.#listeners.get(event) ?? [])];
    let invoked = 0;
    for (const registration of snapshot) {
      if (registration.once) {
        // Nested emits may have already consumed this snapshot entry.
        if (registration.consumed) continue;
        registration.consumed = true;
        registration.unsubscribe();
      }

      const fn = registration.fn;
      invoked++;
      fn(...args);
    }
    return invoked;
  }
}

