export function mergeIntervals(intervals) {
  if (!Array.isArray(intervals)) {
    throw new TypeError('Expected an array of interval pairs');
  }

  const sorted = [];
  for (let i = 0; i < intervals.length; i += 1) {
    const pair = intervals[i];
    if (!Array.isArray(pair) || pair.length !== 2) {
      throw new TypeError('Expected an interval pair');
    }
    const [start, end] = pair;
    if (!Number.isFinite(start) || !Number.isFinite(end) || start > end) {
      throw new TypeError('Expected finite endpoints with start <= end');
    }
    sorted.push([start, end]);
  }

  sorted.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
  const merged = [];
  for (const pair of sorted) {
    const previous = merged[merged.length - 1];
    if (previous && pair[0] <= previous[1]) {
      previous[1] = Math.max(previous[1], pair[1]);
    } else {
      merged.push(pair);
    }
  }
  return merged;
}

