export async function mapLimit(items, limit, fn) {
  if (!Number.isInteger(limit) || limit <= 0) {
    throw new TypeError('limit must be a positive integer');
  }

  const length = items.length;
  const results = new Array(length);
  if (length === 0) return results;

  return new Promise((resolve, reject) => {
    let next = 0;
    let active = 0;
    let completed = 0;
    let failed = false;

    function fail(error) {
      if (failed) return;
      failed = true;
      reject(error);
    }

    function start() {
      while (!failed && active < limit && next < length) {
        const index = next++;
        active++;
        let value;
        try {
          value = fn(items[index], index);
        } catch (error) {
          fail(error);
          return;
        }

        Promise.resolve(value).then((result) => {
          active--;
          if (failed) return;
          results[index] = result;
          completed++;
          if (completed === length) {
            resolve(results);
          } else {
            start();
          }
        }, fail);
      }
    }

    start();
  });
}

