export function sumMoney(values) {
  let total = 0n;

  for (const value of values) {
    if (typeof value !== 'string') {
      throw new TypeError('Money values must be decimal strings');
    }

    const match = /^(-?)([0-9]+)(?:\.([0-9]{1,2}))?$/.exec(value);
    // The dollar anchor can match before a final newline; require a full match.
    if (!match || match[0] !== value) {
      throw new TypeError('Invalid money string');
    }

    const cents = BigInt(match[2]) * 100n
      + BigInt((match[3] ?? '').padEnd(2, '0'));
    total += match[1] === '-' ? -cents : cents;
  }

  const sign = total < 0n ? '-' : '';
  const magnitude = total < 0n ? -total : total;
  return `${sign}${magnitude / 100n}.${(magnitude % 100n).toString().padStart(2, '0')}`;
}

