export async function retry(fn, options) {
  const { attempts, baseDelay, maxDelay, shouldRetry, sleep } = options;

  if (!Number.isInteger(attempts) || attempts <= 0) {
    throw new RangeError('attempts must be a positive integer');
  }
  if (!Number.isFinite(baseDelay) || baseDelay < 0) {
    throw new RangeError('baseDelay must be a finite nonnegative number');
  }
  if (!Number.isFinite(maxDelay) || maxDelay < 0) {
    throw new RangeError('maxDelay must be a finite nonnegative number');
  }

  let delay = Math.min(maxDelay, baseDelay);
  for (let attempt = 1; ; attempt += 1) {
    try {
      return await fn(attempt);
    } catch (error) {
      if (attempt >= attempts || !shouldRetry(error, attempt)) {
        throw error;
      }
      await sleep(delay);
      // Double the capped delay to avoid 0 * Infinity at large attempts.
      delay = Math.min(maxDelay, delay * 2);
    }
  }
}

