  #capacity;
  #entries = new Map();

  constructor(capacity) {
    if (!Number.isInteger(capacity) || capacity <= 0) {
      throw new TypeError('capacity must be a positive integer');
    }
    this.#capacity = capacity;
  }

  set(key, value, ttl, now) {
    if (!Number.isFinite(ttl) || ttl < 0) {
      throw new TypeError('ttl must be a finite nonnegative number');
    }
    if (!Number.isFinite(now)) {
      throw new TypeError('now must be a finite number');
    }

    for (const [storedKey, entry] of this.#entries) {
      if (now >= entry.expires) {
        this.#entries.delete(storedKey);
      }
    }

    // Reinsertion makes this key the most recently used entry.
    this.#entries.delete(key);
    if (ttl === 0) return;

    this.#entries.set(key, { value, expires: now + ttl });
    if (this.#entries.size > this.#capacity) {
      this.#entries.delete(this.#entries.keys().next().value);
    }
  }

