    throw new TypeError('header must start with bytes=');
  }

  const tokens = header.slice('bytes='.length).split(',');
  if (tokens.length === 0) {
    throw new TypeError('at least one range is required');
  }

  const ranges = [];
  for (const rawToken of tokens) {
    const token = rawToken.trim();
    let match;

    if ((match = /^(\d+)-(\d*)$/.exec(token))) {
      const start = Number(match[1]);
      const end = match[2] === '' ? undefined : Number(match[2]);
      if (!Number.isSafeInteger(start) || (end !== undefined && !Number.isSafeInteger(end))) {
        throw new TypeError('range values must be safe integers');
      }
      if (end !== undefined && start > end) {
        throw new TypeError('range start must not exceed range end');
      }

