export const parseCsv = text => {
  if (text.length === 0) return [];

  const rows = [];
  let row = [];
  let field = '';
  let state = 'start';

  const finishField = () => {
    row.push(field);
    field = '';
    state = 'start';
  };

  const finishRow = () => {
    finishField();
    rows.push(row);
    row = [];
  };

  for (let i = 0; i < text.length; i += 1) {
    const ch = text[i];

    if (state === 'quoted') {
      if (ch === '"') {
        if (text[i + 1] === '"') {
          field += '"';
          i += 1;
        } else {
          state = 'closed';
        }
      } else {
        field += ch;
      }
      continue;
    }

    if (state === 'closed') {
      if (ch === ',') {
        finishField();
      } else if (ch === '\n') {
        finishRow();
      } else if (ch === '\r' && text[i + 1] === '\n') {
        finishRow();
        i += 1;
      } else {
        throw new SyntaxError('Unexpected character after closing quote');
      }
      continue;
    }

    if (state === 'start') {
      if (ch === '"') {
        state = 'quoted';
      } else if (ch === ',') {
        finishField();
      } else if (ch === '\n') {
        finishRow();
      } else if (ch === '\r') {
        if (text[i + 1] !== '\n') throw new SyntaxError('Bare CR outside quotes');
        finishRow();
        i += 1;
      } else {
        field += ch;
        state = 'unquoted';
      }
      continue;
    }

    if (ch === ',') {
      finishField();
    } else if (ch === '\n') {
      finishRow();
    } else if (ch === '\r') {
      if (text[i + 1] !== '\n') throw new SyntaxError('Bare CR outside quotes');
      finishRow();
      i += 1;
    } else if (ch === '"') {
      throw new SyntaxError('Quote inside unquoted field');
    } else {
      field += ch;
    }
  }

  if (state === 'quoted') throw new SyntaxError('Unterminated quoted field');
  if (row.length > 0 || field.length > 0 || state === 'closed' || state === 'unquoted' || (text.length > 0 && !/[\r\n]$/.test(text))) {
    finishField();
    rows.push(row);
  }

  return rows;
