export class Emitter {
  constructor() {
    this.listeners = new Map();
  }

  on(event, callback) {
    return this.#add(event, callback, false);
  }

  once(event, callback) {
    return this.#add(event, callback, true);
  }

  #add(event, callback, once) {
    const registration = { callback, once, consumed: false };
    let registrations = this.listeners.get(event);
    if (!registrations) {
      registrations = [];
      this.listeners.set(event, registrations);
    }
    registrations.push(registration);

    let active = true;
    return () => {
      if (!active) return;
      active = false;
      const current = this.listeners.get(event);
      if (!current) return;
      const index = current.indexOf(registration);
      if (index !== -1) current.splice(index, 1);
      if (current.length === 0) this.listeners.delete(event);
    };
  }

  emit(event, ...args) {
    const snapshot = this.listeners.get(event)?.slice();
    if (!snapshot) return 0;

    let invoked = 0;
    for (const registration of snapshot) {
      if (registration.once && registration.consumed) continue;
      if (registration.once) {
