export const mapLimit = (items, limit, fn) => {
  if (!Number.isInteger(limit) || limit <= 0) {
    return Promise.reject(new TypeError('limit must be a positive integer'));
  }

  const length = items.length;
  if (length === 0) return Promise.resolve([]);

  return new Promise((resolve, reject) => {
    let nextIndex = 0;
    let active = 0;
    let completed = 0;
    let failed = false;
    const results = new Array(length);

    const schedule = () => {
      while (!failed && active < limit && nextIndex < length) {
        const index = nextIndex++;
        active++;

        let value;
        try {
          value = fn(items[index], index);
        } catch (error) {
          failed = true;
          reject(error);
          return;
        }

        Promise.resolve(value).then(
          result => {
            active--;
            if (failed) return;
            results[index] = result;
            completed++;
            if (completed === length) {
              resolve(results);
            } else {
              schedule();
            }
          },
          error => {
            active--;
            if (!failed) {
              failed = true;
              reject(error);
            }
          },
        );
      }
    };

    schedule();
  });
};

