export class TtlLru {
  constructor(capacity) {
    if (!Number.isInteger(capacity) || capacity <= 0) {
      throw new TypeError('capacity must be a positive integer');
    }

    // Map iteration order tracks recency: oldest first, newest last.
    this.data = new Map();
    this.capacity = capacity;
  }

  set(key, value, ttl, now) {
    if (!Number.isFinite(now) || !Number.isFinite(ttl) || ttl < 0) {
      throw new TypeError('now and ttl must be finite numbers, and ttl must be non-negative');
    }

    // Expiry is inclusive. Scan the entire map because caller timestamps may
    // move backwards, so expiry order need not match recency order.
    for (const [entryKey, entry] of this.data) {
      if (now >= entry.expires) this.data.delete(entryKey);
    }

    if (ttl === 0) {
      this.data.delete(key);
      return;
    }

    // Delete before inserting so an update refreshes recency without causing
    // an unrelated entry to be evicted.
    this.data.delete(key);
    this.data.set(key, { value, expires: now + ttl });

    if (this.data.size > this.capacity) {
      const oldestKey = this.data.keys().next().value;
      this.data.delete(oldestKey);
    }
  }

  get(key, now) {
    if (!Number.isFinite(now)) {
      throw new TypeError('now must be a finite number');
    }

    const entry = this.data.get(key);
    if (entry === undefined) return undefined;
    if (now >= entry.expires) {
      this.data.delete(key);
      return undefined;
    }

    this.data.delete(key);
    this.data.set(key, entry);
    return entry.value;
  }
}

