    const ch = text[i];

    if (state === 'quoted') {
      if (ch === '"') {
        if (text[i + 1] === '"') {
          field += '"';
          i++;
        } else {
          state = 'after-quote';
        }
      } else {
        field += ch;
      }
      continue;
