export function sumMoney(values) {
  let totalCents = 0n;

  for (const value of values) {
    if (typeof value !== 'string') {
      throw new TypeError('Money values must be decimal strings');
    }

    const match = /^(-?)(\d+)(?:\.(\d{1,2}))?$/.exec(value);
    if (!match) {
      throw new TypeError(`Invalid money value: ${value}`);
    }

    const [, sign, whole, fraction = ''] = match;
    const cents = BigInt(whole) * 100n + BigInt(fraction.padEnd(2, '0') || '0');
    totalCents += sign === '-' ? -cents : cents;
  }

  const negative = totalCents < 0n;
  const absoluteCents = negative ? -totalCents : totalCents;
  const whole = absoluteCents / 100n;
  const fraction = (absoluteCents % 100n).toString().padStart(2, '0');
  return `${negative ? '-' : ''}${whole}.${fraction}`;
}

