export const topoSort = (nodes, edges) => {
  if (!Array.isArray(nodes) || !Array.isArray(edges)) {
    throw new Error('nodes and edges must be arrays');
  }

  const indexByNode = new Map();
  for (let i = 0; i < nodes.length; i += 1) {
    const node = nodes[i];
    if (typeof node !== 'string' || indexByNode.has(node)) {
      throw new Error('nodes must contain distinct strings');
    }
    indexByNode.set(node, i);
  }

  const outgoing = nodes.map(() => new Set());
  const indegree = nodes.map(() => 0);
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 2) {
      throw new Error('each edge must be a [from, to] pair');
    }
    const [from, to] = edge;
    if (!indexByNode.has(from) || !indexByNode.has(to)) {
      throw new Error('edge endpoint is not a known node');
    }
    const fromIndex = indexByNode.get(from);
    const toIndex = indexByNode.get(to);
    if (!outgoing[fromIndex].has(toIndex)) {
      outgoing[fromIndex].add(toIndex);
      indegree[toIndex] += 1;
    }
  }

  // Keep the ready set ordered by original position so each choice is the
  // earliest node among every node that is currently available.
  const ready = [];
  const insertReady = (index) => {
    let low = 0;
    let high = ready.length;
    while (low < high) {
      const middle = (low + high) >>> 1;
      if (ready[middle] < index) low = middle + 1;
      else high = middle;
    }
    ready.splice(low, 0, index);
  };

  for (let i = 0; i < nodes.length; i += 1) {
    if (indegree[i] === 0) insertReady(i);
  }

  const result = [];
  while (ready.length > 0) {
    const current = ready.shift();
    result.push(nodes[current]);
    for (const next of outgoing[current]) {
      indegree[next] -= 1;
      if (indegree[next] === 0) insertReady(next);
    }
  }

  if (result.length !== nodes.length) throw new Error('graph contains a cycle');
  return result;
