  for (let i = 0; i < nodes.length; i += 1) {
    const node = nodes[i];
    if (typeof node !== 'string') throw new Error('nodes must be strings');
    if (indexByNode.has(node)) throw new Error(`duplicate node: ${node}`);
    indexByNode.set(node, i);
  }

  const outgoing = Array.from({ length: nodes.length }, () => []);
  const indegree = Array(nodes.length).fill(0);
  const seenEdges = new Set();
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 2) {
      throw new Error('each edge must be a [from, to] pair');
    }
    const [from, to] = edge;
    if (!indexByNode.has(from) || !indexByNode.has(to)) {
      throw new Error('edge endpoint is not a known node');
    }
    const fromIndex = indexByNode.get(from);
    const toIndex = indexByNode.get(to);
    const key = `${fromIndex}:${toIndex}`;
    if (seenEdges.has(key)) continue;
    seenEdges.add(key);
    outgoing[fromIndex].push(toIndex);
    indegree[toIndex] += 1;
  }

  // A min-heap keeps the earliest original node among all currently ready nodes.
  const ready = [];
  const push = (value) => {
    let i = ready.length;
    ready.push(value);
    while (i > 0) {
      const parent = Math.floor((i - 1) / 2);
      if (ready[parent] <= value) break;
      ready[i] = ready[parent];
      i = parent;
    }
    ready[i] = value;
