  const pop = () => {
    const first = ready[0];
    const last = ready.pop();
    if (ready.length > 0) {
      let i = 0;
      while (true) {
        const left = 2 * i + 1;
        const right = left + 1;
        if (left >= ready.length) break;
        const child = right < ready.length && ready[right] < ready[left] ? right : left;
        if (ready[child] >= last) break;
        ready[i] = ready[child];
        i = child;
      }
      ready[i] = last;
    }
