export const topoSort = (nodes, edges) => {
  if (!Array.isArray(nodes) || !Array.isArray(edges)) {
    throw new Error('nodes and edges must be arrays');
  }

  const indexByNode = new Map();
  for (let i = 0; i < nodes.length; i += 1) {
    const node = nodes[i];
    if (typeof node !== 'string') throw new Error('nodes must be strings');
    if (indexByNode.has(node)) throw new Error('duplicate node');
    indexByNode.set(node, i);
  }

  const outgoing = nodes.map(() => new Set());
  const indegree = nodes.map(() => 0);
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 2 ||
        typeof edge[0] !== 'string' || typeof edge[1] !== 'string') {
      throw new Error('each edge must be a [from, to] pair of strings');
    }
    const from = indexByNode.get(edge[0]);
    const to = indexByNode.get(edge[1]);
    if (from === undefined || to === undefined) throw new Error('unknown edge endpoint');
    if (!outgoing[from].has(to)) {
      outgoing[from].add(to);
      indegree[to] += 1;
    }
  }

  // A min-heap of original node indices keeps the earliest currently
  // available node at the root, including nodes released by each removal.
  const ready = [];
  const push = (value) => {
    let i = ready.length;
    ready.push(value);
    while (i > 0) {
      const parent = (i - 1) >> 1;
      if (ready[parent] <= value) break;
      ready[i] = ready[parent];
      i = parent;
    }
    ready[i] = value;
  };
  const pop = () => {
    const first = ready[0];
    const last = ready.pop();
    if (ready.length > 0) {
      let i = 0;
      while (true) {
        const left = 2 * i + 1;
        if (left >= ready.length) break;
        const right = left + 1;
        const child = right < ready.length && ready[right] < ready[left] ? right : left;
        if (ready[child] >= last) break;
        ready[i] = ready[child];
        i = child;
      }
      ready[i] = last;
    }
    return first;
  };

  for (let i = 0; i < nodes.length; i += 1) {
    if (indegree[i] === 0) push(i);
  }

  const result = [];
  while (ready.length > 0) {
    const current = pop();
    result.push(nodes[current]);
    for (const next of outgoing[current]) {
      indegree[next] -= 1;
      if (indegree[next] === 0) push(next);
    }
  }

  if (result.length !== nodes.length) throw new Error('cycle detected');
  return result;
};

