export class TtlLru {
  constructor(capacity) {
    if (!Number.isInteger(capacity) || capacity <= 0) {
      throw new TypeError('capacity must be a positive integer');
    }
    this.capacity = capacity;
    this.data = new Map();
  }

  set(key, value, ttl, now) {
    if (!Number.isFinite(ttl) || ttl < 0 || !Number.isFinite(now)) {
      throw new TypeError('ttl and now must be finite numbers, and ttl must be nonnegative');
    }

    for (const [storedKey, entry] of this.data) {
      if (now >= entry.expires) this.data.delete(storedKey);
    }

    if (ttl === 0) {
      this.data.delete(key);
      return;
    }

    // Refreshing an existing key must not make room by evicting another key.
    this.data.delete(key);
    if (this.data.size >= this.capacity) {
      const leastRecentlyUsed = this.data.keys().next().value;
      this.data.delete(leastRecentlyUsed);
    }
    this.data.set(key, { value, expires: now + ttl });
  }

  get(key, now) {
    if (!Number.isFinite(now)) {
      throw new TypeError('now must be a finite number');
    }

    const entry = this.data.get(key);
    if (entry === undefined) return undefined;
    if (now >= entry.expires) {
      this.data.delete(key);
      return undefined;
    }

    this.data.delete(key);
    this.data.set(key, entry);
    return entry.value;
  }
}

